.gzp-desk{
          háttér:
            radiális gradiens (120% 70% 50% 0%, rgba (214,178,110,.05), átlátszó 58%),
            radiális gradiens (130% 100% 50% 108%, rgba(0,0,0,.34), átlátszó 62%),
            /* fa erezet – szélesen és szabálytalanul elhelyezkedő (régi hajszálak
               Bársonynak tűnt) */
            ismétlődő-lineáris-gradiens(92 fok,
              rgba(0;0;0;.13) 0 3px,
              átlátszó 3px 17px,
              rgba(255 255 255, .016) 17 képpont 20 képpont,
              átlátszó 20px 41px,
              rgba(0;0;0;.09) 41px 43px,
              átlátszó 43 képpont 74 képpont),
            /* a táblák illesztései */
            ismétlődő-lineáris-gradiens (90 fok,
              rgba(0;0;0;.42) 0 2px,
              átlátszó 2px 148px),
            lineáris gradiens (180 fok, #33261a 0%, #291e13 52%, #1c150d 100%);
        }
        .gzp-under{
          pozíció: abszolút;
          betét: 0;
          háttér: lineáris gradiens(180 fok, #e6d9b6 0%, #d6c599 100%);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), beillesztés 0 0 0 1px rgba(120,90,36,.2);
          transzformáció: forgatás(-1.15deg) translateY(5px);
        }
        .gzp-under--2{
          háttér: lineáris gradiens(180 fok, #e1d2ab 0%, #cfbd90 100%);
          transzformáció: forgatás(.85deg) translateY(9px);
        }
